/** Two normal JVMs; manifest contains identities/expectations only, never reconstructed entity payloads. */
@GameTestHolder("dreamseekers_firefly_rush_restart")
@PrefixGameTestTemplate(false)
public final class FireflyRushSkillRestartGameTests {
    private static final String OWNER="FireflyRushRestart_Owner";
    private static final BlockPos ORIGIN=new BlockPos(65536,90,65536);
    private static final File MANIFEST=new File("firefly-rush-skill-restart-expectations.nbt");
    private static final UUID MOVE_TECH=UUID.fromString("2ca4c969-d72e-43e5-aa53-82644d87ee01"),FLY_TECH=UUID.fromString("2ca4c969-d72e-43e5-aa53-82644d87ee02");
    private static FakePlayer owner;
    @GameTest(template="unit_isolation_arena",batch="dreamseekers_firefly_rush_restart",timeoutTicks=1500)
    public static void normalRestartPreservesPaidCooldownAndPermanentFlightButNeverReplaysRushOrStaleWork(GameTestHelper h) throws Exception {
        switch(System.getProperty("dreamseekers.firefly.rush.test.phase","")){case "prepare"->prepare(h);case "verify"->verify(h);default->throw new IllegalArgumentException("Unknown Firefly Rush restart phase");}
    }
    private static void prepare(GameTestHelper h){
        ServerLevel level=h.getLevel();h.assertTrue(!MANIFEST.exists()&&PlayerServerEvents.getRTSPlayer(OWNER)==null,"fresh isolated prepare world, not a reused spent verification");CompoundTag expected=new CompoundTag();expected.putLong("prepareJvmStart",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());List<Long> forced=new ArrayList<>();for(int x=4096;x<=4097;x++)for(int z=4096;z<=4097;z++){long key=ChunkPos.asLong(x,z);h.assertTrue(!level.getForcedChunks().contains(key),"do not adopt another fixture's chunk ticket");level.setChunkForced(x,z,true);forced.add(key);}expected.putLongArray("forcedChunks",forced);arena(level);PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewBot(OWNER,DreamseekersMod.DREAMSEEKERS));ResourcesServerEvents.resourcesList.add(new Resources(OWNER,123,234,345,456));player(level);
        var spent=spawn(h,4,1,8,1901);var unused=spawn(h,4,1,20,1902);BlockPos oldLog=at(23,2,8);level.setBlock(oldLog,Blocks.OAK_LOG.defaultBlockState(),3);expected.putLong("oldLog",oldLog.asLong());expected.putUUID("spent",spent.getUUID());expected.putUUID("unused",unused.getUUID());spent.getAttribute(Attributes.MOVEMENT_SPEED).addPermanentModifier(new AttributeModifier(MOVE_TECH,"native permanent movement research",.025,AttributeModifier.Operation.ADDITION));spent.getAttribute(Attributes.FLYING_SPEED).addPermanentModifier(new AttributeModifier(FLY_TECH,"native permanent flying research",.025,AttributeModifier.Operation.ADDITION));expected.putDouble("moveBase",spent.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue());expected.putDouble("flyBase",spent.getAttribute(Attributes.FLYING_SPEED).getBaseValue());expected.putDouble("moveWithPermanent",spent.getAttributeValue(Attributes.MOVEMENT_SPEED));expected.putDouble("flyWithPermanent",spent.getAttributeValue(Attributes.FLYING_SPEED));Vec3[] paused={null};int[] progress={0};
        h.startSequence().thenWaitUntil(()->{published(h,spent);published(h,unused);published(h,owner);h.assertTrue(level.isPositionEntityTicking(oldLog)&&level.areEntitiesLoaded(new ChunkPos(oldLog).toLong()),"target really entity-ticking before actual work command");})
          .thenExecute(()->{ledger(h);spent.setNoAi(false);command(h,spent,UnitAction.MOVE,oldLog);})
          .thenWaitUntil(()->h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(spent.getId())&&oldLog.equals(spent.getGatherResourceGoal().getGatherTarget())&&!spent.getNavigation().isDone()&&spent.position().distanceTo(Vec3.atCenterOf(oldLog))>8,"actual authenticated distant work route runs before pause, not a manually assigned intent"))
          .thenExecute(()->{h.assertTrue(cast(level,spent)==SkillResult.SUCCESS,"real owner pays for personal rush while native work path is current");h.assertTrue(FireflyRush.active(spent)&&FireflyRush.hasPausedWork(spent)&&spent.getNavigation().isDone(),"real live rush stops only its actual current work navigation");paused[0]=spent.position();progress[0]=spent.getGatherResourceGoal().getGatherTicksLeft();})
          .thenIdle(10).thenExecute(()->{h.assertTrue(FireflyRush.remainingTicks(spent)==90&&FireflyRush.hasPausedWork(spent)&&spent.getNavigation().isDone()&&spent.position().distanceToSqr(paused[0])<.04&&spent.getGatherResourceGoal().getGatherTicksLeft()==progress[0],"ordinary save snapshot has actual live ninety-tick rush and paused unchanged work");h.assertTrue(level.getBlockState(oldLog).is(Blocks.OAK_LOG),"no cargo was produced before prepare save");close(h,spent.getAttributeValue(Attributes.FLYING_SPEED),expected.getDouble("flyWithPermanent")*1.35,"real live temporary flight increase exists before normal save");expected.putLong("snapshotGameTime",level.getGameTime());expected.putInt("spentCD",spent.rts().skills().cooldownTicks(UnitSkill.FIREFLY_RUSH));expected.putLong("revision",spent.rts().skills().revision());expected.putFloat("health",spent.getHealth());h.assertTrue(expected.getInt("spentCD")==490&&unused.rts().skills().cooldownTicks(UnitSkill.FIREFLY_RUSH)==0,"paid and genuinely unused worker cooldowns are distinct");ledger(h);try{NbtIo.writeCompressed(expected,MANIFEST);}catch(Exception failure){throw new RuntimeException(failure);}System.out.println("DREAMSEEKERS_FIREFLY_RUSH_RESTART_PREPARED uuid="+spent.getUUID()+" gameTime="+level.getGameTime()+" liveRush="+FireflyRush.remainingTicks(spent)+" cooldown="+expected.getInt("spentCD")+" oldWork="+oldLog+" cargo="+spent.getItems());}).thenSucceed();
    }
    private static void verify(GameTestHelper h) throws Exception {
        ServerLevel level=h.getLevel();h.assertTrue(MANIFEST.isFile(),"prepare expectation manifest exists");CompoundTag expected=NbtIo.readCompressed(MANIFEST);h.assertTrue(expected.getLong("prepareJvmStart")!=java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime(),"genuinely separate JVM, not same-process NBT simulation");for(long key:expected.getLongArray("forcedChunks")){h.assertTrue(level.getForcedChunks().contains(key),"ordinary world persisted exact fixture chunk ticket");var c=new ChunkPos(key);level.getChunk(c.x,c.z);}player(level);FireflyWorker[] units=new FireflyWorker[2];BlockPos oldLog=BlockPos.of(expected.getLong("oldLog"));BlockPos[] newLog={null};long[] observed={0};
        h.startSequence().thenWaitUntil(()->{for(String key:List.of("spent","unused")){var body=level.getEntity(expected.getUUID(key));h.assertTrue(body instanceof FireflyWorker,"normal world loader restored original actual UUID: "+key);published(h,body);}published(h,owner);})
          .thenExecute(()->{units[0]=(FireflyWorker)level.getEntity(expected.getUUID("spent"));units[1]=(FireflyWorker)level.getEntity(expected.getUUID("unused"));var spent=units[0];long elapsed=level.getGameTime()-expected.getLong("snapshotGameTime");observed[0]=elapsed;h.assertTrue(elapsed>=0&&elapsed<400,"second-JVM check occurs while original paid500 deadline remains meaningfully live: "+elapsed);for(int i=0;i<units.length;i++){var w=units[i];h.assertTrue(w.getOwnerName().equals(OWNER)&&w.getScenarioRoleIndex()==1901+i&&UnitServerEvents.getAllUnits().stream().filter(e->e.getUUID().equals(w.getUUID())).count()==1,"original owner/scenario/exactly one roster UUID survives normally");h.assertTrue(!FireflyRush.active(w)&&!FireflyRush.hasPausedWork(w)&&FireflyRush.remainingTicks(w)==0,"short personal speed and pause lease never replay from persisted work/cooldown");close(h,SkillEffects.bonus(w,BuffKind.MOVEMENT_SPEED),0,"no temporary speed contribution on load");}close(h,spent.getHealth(),expected.getFloat("health"),"no hidden hostile AI or reload damage");h.assertTrue(spent.getAttribute(Attributes.MOVEMENT_SPEED).getModifier(MOVE_TECH)!=null&&spent.getAttribute(Attributes.FLYING_SPEED).getModifier(FLY_TECH)!=null,"both exact permanent native modifiers survive");close(h,spent.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue(),expected.getDouble("moveBase"),"movement base not rewritten");close(h,spent.getAttribute(Attributes.FLYING_SPEED).getBaseValue(),expected.getDouble("flyBase"),"flight base not rewritten");close(h,spent.getAttributeValue(Attributes.MOVEMENT_SPEED),expected.getDouble("moveWithPermanent"),"only permanent movement remains");close(h,spent.getAttributeValue(Attributes.FLYING_SPEED),expected.getDouble("flyWithPermanent"),"only permanent flight remains");int remaining=(int)(expected.getInt("spentCD")-elapsed);h.assertTrue(spent.rts().skills().cooldownTicks(UnitSkill.FIREFLY_RUSH)==remaining&&remaining>0&&spent.rts().skills().revision()>=expected.getLong("revision"),"original absolute cooldown/replay revision neither refunds nor resets");h.assertTrue(cast(level,spent)==SkillResult.COOLDOWN,"normal load cannot recast paid skill for free");h.assertTrue(units[1].rts().skills().cooldownTicks(UnitSkill.FIREFLY_RUSH)==0&&cast(level,units[1])==SkillResult.SUCCESS,"genuinely unused normally loaded worker may perform a new authenticated activation");ledger(h);h.assertTrue(level.getBlockState(oldLog).is(Blocks.OAK_LOG),"distant old resource has not incidentally harvested before the check");command(h,spent,UnitAction.STOP,BlockPos.ZERO);})
          .thenWaitUntil(()->h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(units[0].getId())&&units[0].getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&units[0].getMoveGoal().getMoveTarget()==null,"new real STOP clears whichever native task normally persisted; no assumption that all vanilla work is unsaved"))
          .thenExecute(()->{var spent=units[0];BlockPos target=spent.blockPosition().offset(3,1,0);h.assertTrue(level.getBlockState(target).isAir()&&target.getX()<ORIGIN.getX()+29&&target.getZ()<ORIGIN.getZ()+29,"new nearby valid work position remains inside constructed room");newLog[0]=target;level.setBlock(target,Blocks.OAK_LOG.defaultBlockState(),3);spent.setNoAi(false);command(h,spent,UnitAction.MOVE,target);})
          .thenWaitUntil(()->{var goal=units[0].getGatherResourceGoal();h.assertTrue(newLog[0].equals(goal.getGatherTarget())&&goal.isGathering()&&goal.data.targetResourceSource!=null&&goal.getGatherTicksLeft()>0&&goal.getGatherTicksLeft()<goal.data.targetResourceSource.ticksToGather,"new authenticated post-restart gathering actually progresses at native rate, not a getter-only pause release");})
          .thenExecute(()->{ledger(h);h.assertTrue(level.getBlockState(newLog[0]).is(Blocks.OAK_LOG)&&level.getBlockState(oldLog).is(Blocks.OAK_LOG),"positive records real work progress before any valued cargo; avoids confusing native save-time cargo settlement with a new skill economy");command(h,units[0],UnitAction.STOP,BlockPos.ZERO);})
          .thenWaitUntil(()->h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(units[0].getId())&&units[0].getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE,"latest post-restart STOP accepted"))
          .thenIdle(35).thenWaitUntil(()->h.assertTrue(level.getGameTime()>=expected.getLong("snapshotGameTime")+90,"observe through the actual original pre-restart rush deadline, never guess from method duration")).thenExecute(()->{h.assertTrue(units[0].getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&units[0].getMoveGoal().getMoveTarget()==null&&level.getBlockState(oldLog).is(Blocks.OAK_LOG)&&level.getBlockState(newLog[0]).is(Blocks.OAK_LOG),"no delayed rush expiry restores old native work over later explicit commands");ledger(h);System.out.println("DREAMSEEKERS_FIREFLY_RUSH_RESTART_UUID_PAID_CD_NO_PAUSE_REPLAY_PASS elapsedAtLoad="+observed[0]+" remainingCD="+units[0].rts().skills().cooldownTicks(UnitSkill.FIREFLY_RUSH)+" uuid="+units[0].getUUID());for(var w:units)w.discard();owner.serverLevel().removePlayerImmediately(owner,Entity.RemovalReason.DISCARDED);owner=null;PlayerServerEvents.players.removeIf(p->p.getGameProfile().getName().equals(OWNER));PlayerServerEvents.rtsPlayers.removeIf(p->p.name.equals(OWNER));ResourcesServerEvents.resourcesList.removeIf(r->r.ownerName.equals(OWNER));for(long key:expected.getLongArray("forcedChunks")){var c=new ChunkPos(key);level.setChunkForced(c.x,c.z,false);}}).thenSucceed();
    }
    private static SkillResult cast(ServerLevel level,FireflyWorker w){return SkillService.request(player(level),new SkillRequest(UnitSkill.FIREFLY_RUSH,w.getId(),w.getUUID(),w.rts().skills().revision(),w.getId(),w.getUUID()));}
    private static FireflyWorker spawn(GameTestHelper h,int x,int y,int z,int scenario){var w=DreamseekersMod.FIREFLY_WORKER.get().create(h.getLevel());w.setOwnerName(OWNER);w.setScenarioRoleIndex(scenario);w.setNoAi(true);w.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);var p=at(x,y,z);w.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5);h.assertTrue(h.getLevel().addFreshEntity(w),"actual native worker added to normal entity storage");return w;}
    private static void published(GameTestHelper h,Entity e){h.assertTrue(e.tickCount>3&&h.getLevel().getEntity(e.getId())==e&&h.getLevel().getEntity(e.getUUID())==e,"actual original object published with natural ticks: "+e.getUUID()+" ticks="+e.tickCount);}
    private static BlockPos at(int x,int y,int z){return ORIGIN.offset(x,y,z);}
    private static FakePlayer player(ServerLevel level){if(owner==null){owner=new FakePlayer(level,new GameProfile(UUID.nameUUIDFromBytes(OWNER.getBytes(java.nio.charset.StandardCharsets.UTF_8)),OWNER));owner.connection=new SilentHandler(owner);var p=at(2,1,27);owner.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5);level.addNewPlayer(owner);PlayerServerEvents.players.add(owner);}return owner;}
    private static void command(GameTestHelper h,FireflyWorker w,UnitAction action,BlockPos target){var sender=player(h.getLevel());try{var c=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);c.setListener(sender.connection);var ctor=net.minecraftforge.network.NetworkEvent.Context.class.getDeclaredConstructor(net.minecraft.network.Connection.class,net.minecraftforge.network.NetworkDirection.class,int.class);ctor.setAccessible(true);var context=ctor.newInstance(c,net.minecraftforge.network.NetworkDirection.PLAY_TO_SERVER,-1);h.assertTrue(context.getSender()==sender,"real authenticated command sender");h.assertTrue(new com.solegendary.reignofnether.unit.packets.UnitActionServerboundPacket(OWNER,action,-1,new int[]{w.getId()},target,BlockPos.ZERO,false).handle(()->context),"actual selected-unit work/STOP packet accepted");}catch(ReflectiveOperationException failure){throw new RuntimeException("real restart command context",failure);}}
    private static void ledger(GameTestHelper h){var r=ResourcesServerEvents.resourcesList.stream().filter(v->v.ownerName.equals(OWNER)).findFirst().orElse(null);h.assertTrue(r!=null,"saved bank remains present, never recreate/fallback");h.assertTrue(r.food==123&&r.wood==234&&r.ore==345&&r.emerald==456&&r.foodToAdd==0&&r.woodToAdd==0&&r.oreToAdd==0&&r.emeraldToAdd==0,"strict original four banks and four pending values, no tolerating historical drift");for(var e:UnitServerEvents.getAllUnits())if(e instanceof Unit u&&u.getOwnerName().equals(OWNER))h.assertTrue(u.getItems().isEmpty(),"explicit no-valued-cargo fixture, never erase/recreate inventory: "+e.getUUID()+" "+u.getItems());System.out.println("FIREFLY_RUSH_RESTART_LEDGER gameTime="+h.getLevel().getGameTime()+" bank="+r.food+","+r.wood+","+r.ore+","+r.emerald+" pending=0 cargo=empty");}
    private static void arena(ServerLevel level){for(int x=0;x<32;x++)for(int z=0;z<32;z++)level.setBlock(at(x,9,z),Blocks.STONE.defaultBlockState(),2);level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(ORIGIN.getX(),ORIGIN.getY()+1,ORIGIN.getZ(),ORIGIN.getX()+32,level.getMaxBuildHeight(),ORIGIN.getZ()+32)).forEach(Entity::discard);for(int x=0;x<32;x++)for(int z=0;z<32;z++){level.setBlock(at(x,0,z),Blocks.STONE.defaultBlockState(),2);for(int y=1;y<9;y++)level.setBlock(at(x,y,z),(x==0||x==31||z==0||z==31?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}var drops=level.getEntitiesOfClass(ItemEntity.class,new AABB(ORIGIN,ORIGIN.offset(32,10,32)));System.out.println("FIREFLY_RUSH_RESTART_CONSTRUCTION_DROPS count="+drops.size());drops.forEach(Entity::discard);}
    private static void close(GameTestHelper h,double actual,double expected,String why){h.assertTrue(Double.isFinite(actual)&&Math.abs(actual-expected)<.0005,why+" expected="+expected+" actual="+actual);}
    private static final class SilentHandler extends ServerGamePacketListenerImpl{SilentHandler(ServerPlayer p){super(p.serverLevel().getServer(),new SilentConnection(),p);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
    private static final class SilentConnection extends net.minecraft.network.Connection{SilentConnection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
}
